# -*- coding: utf-8 -*-
"""Trang Bang tra ma: Tooley Phu luc 5 (thap phan, bat phan, thap luc, nhi phan, ASCII 0-127) sinh bang chuong trinh (numlib/codes.py, hai cach tinh), may doi ma va Luyen doi ma."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'numlib'))
import codes as C
from hx import esc

def body(lang):
    vi = lang == 'vi'
    h = f'<h1>{"Bảng tra mã (Tooley Phụ lục 5)" if vi else "Code table (Tooley Appendix 5)"}</h1><p class="lead">' + (
        '128 mã ASCII (0 đến 127) với giá trị thập phân, bát phân, thập lục phân và nhị phân. Các cột số do chương trình sinh (hai cách tính độc lập) rồi đối chiếu với bảng in của sách; cột "Ý nghĩa" theo cột Meaning của sách (đã kiểm trên ảnh trang 391 đến 393).' if vi else
        '128 ASCII codes (0 to 127) with decimal, octal, hexadecimal and binary values. The number columns are generated by program (two independent methods) and compared with the printed table of the book; the "Meaning" column follows the book\'s Meaning column (checked on page images 391 to 393).') + '</p>'
    h += '<div id="codes"></div>'
    h += '<h2>' + ('Máy đổi mã' if vi else 'Code converter') + '</h2><div id="conv"></div><h2>' + ('Luyện đổi mã' if vi else 'Code conversion practice') + '</h2><div id="drill"></div>'
    h += f'<h2>{"Bảng đầy đủ" if vi else "The full table"}</h2><input id="code-q" type="search" placeholder="{"Lọc: ký tự, số, tên…" if vi else "Filter: character, number, name…"}" style="width:100%;max-width:420px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit;margin-bottom:8px">'
    h += '<div class="tablewrap"><table class="t left" id="code-table"><tr><th>' + ('Thập phân' if vi else 'Decimal') + '</th><th>' + ('Bát phân' if vi else 'Octal') + '</th><th>' + ('Thập lục phân' if vi else 'Hex') + '</th><th>' + ('Nhị phân' if vi else 'Binary') + '</th><th>ASCII</th><th>' + ('Ý nghĩa (theo sách)' if vi else 'Meaning (book)') + '</th></tr>'
    for n, o, x, b, sym, mean in C.rows:
        h += f'<tr><td>{n}</td><td>{o}</td><td>{x}</td><td>{b}</td><td><b>{esc(sym)}</b></td><td>{esc(mean)}</td></tr>'
    return h + '</table></div>'
